    /// CSS Color 4 `oklch()` for SwiftUI — Björn Ottosson's Oklab math.
    /// Slightly-out-of-gamut values are clamped per sRGB channel; browsers
    /// instead gamut-map by reducing chroma, so heavily out-of-gamut tokens
    /// could diverge a little from web rendering (in-gamut tokens are exact).
    /// - Parameters: l 0...1, c ~0...0.37, h degrees, alpha 0...1
    static func oklch(_ l: Double, _ c: Double, _ h: Double, alpha: Double = 1.0) -> Color {
        let hr = h * .pi / 180
        let a = c * cos(hr), b = c * sin(hr)
        let l_ = l + 0.3963377774 * a + 0.2158037573 * b
        let m_ = l - 0.1055613458 * a - 0.0638541728 * b
        let s_ = l - 0.0894841775 * a - 1.2914855480 * b
        let L = l_ * l_ * l_, M = m_ * m_ * m_, S = s_ * s_ * s_
        func gamma(_ x: Double) -> Double {
            let v = min(1.0, max(0.0, x))
            return v <= 0.0031308 ? 12.92 * v : 1.055 * pow(v, 1.0 / 2.4) - 0.055
        }
        return Color(.sRGB,
            red:   gamma( 4.0767416621 * L - 3.3077115913 * M + 0.2309699292 * S),
            green: gamma(-1.2684380046 * L + 2.6097574011 * M - 0.3413193965 * S),
            blue:  gamma(-0.0041960863 * L - 0.7034186147 * M + 1.7076147010 * S),
            opacity: alpha)
    }
}

